/**
 * Element emission: `element` DeployableEntity → `elementum_element` +
 * field resources in ei's dialect. No status_options/stages (apps always
 * emit those; element captures do not).
 */
import { workspaceAspectKey } from "../../engine/build/context.js";
import { EntityTfError } from "../../engine/entity.js";
import { expr, snakeSlug } from "../../engine/tf/index.js";
import { accessPolicyToTf } from "../access-policy/to-tf.js";
import { displayBlocksToLayoutSections } from "../app/display-blocks-to-layout.js";
import { APP_RESOURCE_TYPE } from "../app/module.js";
import { displayBlocksToRecordCreateFormSections } from "../app/display-blocks-to-record-create-form.js";
import { dashboardsToTf } from "../dashboard/to-tf.js";
import { fieldToTf } from "../field/to-tf.js";
import { CATEGORY_ORG_BAG } from "../org/category.js";
import { categoryIdExpr, missingCategoryDiagnostic } from "../org/category-ref.js";
import { CLOUD_LINK_ORG_BAG } from "../org/cloud-link.js";
import { recordCreateFormToTf } from "../record-create-form/to-tf.js";
import { relationshipsToTf } from "../relationship/to-tf.js";
import { rolesToTf } from "../role/to-tf.js";
import { relationshipTargetsFromBag, widgetsToTf } from "../widget/to-tf.js";
import { viewToTf } from "../view/to-tf.js";
import { ELEMENT_RESOURCE_TYPE } from "./module.js";
/** System-field tags that fold into the element resource (no field resource). */
const SYSTEM_FIELD_TAGS = new Set([
    "TITLE",
    "HANDLE",
    "STATUS",
    "STAGE",
    "CREATED_AT",
    "CREATED_BY",
    "UPDATED_AT",
    "UPDATED_BY",
    "CLOSED_AT",
    "CLOSED_BY",
]);
/** `elementum_element` + one field resource per custom field. */
export function elementToTf(entity, ctx) {
    if (entity.kind !== "element") {
        throw new EntityTfError(`elementToTf expects kind "element"; got "${entity.kind}" (refName "${entity.refName}")`);
    }
    const payload = entity.payload;
    if (payload === null || typeof payload !== "object") {
        throw new EntityTfError(`element "${entity.refName}" has a non-object payload`);
    }
    const elementAttrs = {
        name: payload.name ?? "",
    };
    // Optional+Computed on the provider: omitting it (rather than forcing a
    // default) lets the platform's current value ride through unchanged.
    if (payload.commentsEnabled !== undefined)
        elementAttrs["comments_enabled"] = payload.commentsEnabled;
    if (payload.namespace !== undefined)
        elementAttrs["namespace"] = payload.namespace;
    if (payload.handle !== undefined)
        elementAttrs["handle"] = payload.handle;
    if (payload.description !== undefined)
        elementAttrs["description"] = payload.description;
    if (payload.icon !== undefined)
        elementAttrs["icon"] = payload.icon;
    if (payload.color !== undefined)
        elementAttrs["color"] = payload.color;
    const hybridTable = payload.cloudOptions?.snowflake?.hybridTable;
    if (payload.cloudOptions !== undefined && payload.cloudConnection !== undefined) {
        throw new EntityTfError(`element "${entity.refName}": cloudOptions and cloudConnection are mutually exclusive`);
    }
    if (hybridTable !== undefined)
        elementAttrs["snowflake_hybrid_table"] = hybridTable;
    // A LINKED element's Snowflake table mapping — create-only (the table
    // binding is immutable once set), but sent every build so a rebuild
    // doesn't null it out on an in-place update.
    const cloudConnection = payload.cloudConnection;
    if (cloudConnection !== undefined) {
        if (cloudConnection.database !== undefined)
            elementAttrs["cloud_mapping_snowflake_database"] = cloudConnection.database;
        if (cloudConnection.schema !== undefined)
            elementAttrs["cloud_mapping_snowflake_schema"] = cloudConnection.schema;
        if (cloudConnection.table !== undefined)
            elementAttrs["cloud_mapping_snowflake_table"] = cloudConnection.table;
        if (cloudConnection.hybridTable !== undefined)
            elementAttrs["snowflake_hybrid_table"] = cloudConnection.hybridTable;
        if (cloudConnection.titleColumnName !== undefined)
            elementAttrs["title_column_name"] = cloudConnection.titleColumnName;
        if (cloudConnection.idColumnName !== undefined)
            elementAttrs["id_column_name"] = cloudConnection.idColumnName;
    }
    const categoryName = payload.category?.name;
    if (categoryName !== undefined && categoryName !== "") {
        const category = ctx.orgRefs.byName(CATEGORY_ORG_BAG, categoryName);
        if (category === undefined) {
            ctx.diagnostics.push(missingCategoryDiagnostic(categoryName));
        }
        else {
            elementAttrs["category_id"] = categoryIdExpr(category);
        }
    }
    const cloudLink = payload.cloudLinkId;
    if (cloudLink !== undefined) {
        const tsLabel = cloudLink.refName ?? "";
        const resolved = ctx.orgRefs.byTsLabel(CLOUD_LINK_ORG_BAG, tsLabel);
        if (resolved === undefined) {
            ctx.diagnostics.push(`cloud link token "${tsLabel}" is not in the org catalog — re-run \`edk pull org --data-only\``);
        }
        else {
            elementAttrs["cloud_link_id"] = expr.dataAttr("elementum_cloudlink", resolved.tfLabel, ["id"]);
        }
    }
    // displayBlocks (LAYOUT surface) → elementum_layout. recordCreateDisplayBlocks
    // (CREATE surface) → elementum_record_create_form. Both mapped below, same
    // mutual-exclusivity precedent: a surface has exactly one terraform target,
    // authored either through the typed builder or through display blocks, not
    // both.
    if (payload.layouts !== undefined && payload.displayBlocks !== undefined) {
        throw new EntityTfError(`element "${entity.refName}": both "layouts" and "displayBlocks" are authored — they both target the record-detail layout; author only one`);
    }
    if (payload.recordCreateForm !== undefined && payload.recordCreateDisplayBlocks !== undefined) {
        throw new EntityTfError(`element "${entity.refName}": both "recordCreateForm" and "recordCreateDisplayBlocks" are authored — they both target the new-record form; author only one`);
    }
    let mappedLayoutSections;
    if (payload.displayBlocks !== undefined) {
        mappedLayoutSections = displayBlocksToLayoutSections(payload.displayBlocks, `element "${entity.refName}" displayBlocks`, ctx.diagnostics);
    }
    let mappedRecordCreateFormSections;
    if (payload.recordCreateDisplayBlocks !== undefined) {
        mappedRecordCreateFormSections = displayBlocksToRecordCreateFormSections(payload.recordCreateDisplayBlocks, `element "${entity.refName}" recordCreateDisplayBlocks`, ctx.diagnostics);
    }
    const blocks = [];
    const fieldAddresses = new Map();
    const fieldNames = new Map();
    const objectId = expr.resourceAttr(ELEMENT_RESOURCE_TYPE, ctx.appTfLabel, ["id"]);
    for (const fieldEntry of payload.fields ?? []) {
        const typeKey = Object.keys(fieldEntry)[0];
        if (typeKey === undefined)
            continue;
        const inner = fieldEntry[typeKey];
        const name = inner.name ?? "";
        const fieldKey = inner.__refName ?? snakeSlug(name);
        if (fieldKey !== "" && name !== "")
            fieldNames.set(fieldKey, name);
        const systemTag = inner.tags?.find((tag) => SYSTEM_FIELD_TAGS.has(tag));
        if (systemTag !== undefined) {
            switch (systemTag) {
                case "TITLE":
                    if (name !== "Title")
                        elementAttrs["title_field_name"] = name;
                    if (inner.description !== undefined)
                        elementAttrs["title_field_description"] = inner.description;
                    break;
                case "HANDLE":
                    if (name !== "ID")
                        elementAttrs["id_field_name"] = name;
                    if (inner.description !== undefined)
                        elementAttrs["id_field_description"] = inner.description;
                    break;
                case "STATUS":
                case "STAGE":
                    ctx.diagnostics.push(`systemFields.${systemTag.toLowerCase()}: elements do not carry status/stages on the terraform path; dropped`);
                    break;
                default:
                    // Audit fields are provider-managed; nothing to emit.
                    break;
            }
            continue;
        }
        const field = fieldToTf(typeKey, inner, {
            ownerTfLabel: ctx.appTfLabel,
            appRefName: ctx.appRefName,
            scope: "element",
            objectId,
            diagnostics: ctx.diagnostics,
            orgRefs: ctx.orgRefs,
            workspaceAspects: ctx.workspaceAspects,
        });
        if (field === undefined)
            continue;
        blocks.push(field.block);
        fieldAddresses.set(field.bagKey, field.address);
    }
    blocks.push(...dashboardsToTf(payload.dashboards, {
        ownerTfLabel: ctx.appTfLabel,
        scope: "element",
        ownerType: "ELEMENT_ASPECT",
        ownerId: objectId,
        ownerRefName: ctx.appRefName,
        ownerResourceType: ELEMENT_RESOURCE_TYPE,
        orgRefs: ctx.orgRefs,
        workspaceAspects: ctx.workspaceAspects,
        diagnostics: ctx.diagnostics,
    }));
    blocks.push(...widgetsToTf(payload.widgets, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        ownerType: ELEMENT_RESOURCE_TYPE,
        scope: "element",
        objectId,
        orgRefs: ctx.orgRefs,
        workspaceAspects: ctx.workspaceAspects,
        diagnostics: ctx.diagnostics,
        fieldAddresses,
        relationshipTargets: relationshipTargetsFromBag(payload.relationships),
    }));
    // An element has exactly one implicit layout (the platform's Initiate
    // stage — see layoutToTf's element-scope stage_id omission) — "layout" is
    // a synthetic bag key here, not a real stage reference. It must match the
    // bridge's own fixed "<prefix>_layout" resource-label convention
    // (cmd/elementum/export/hcl_app.go's generateLayoutIR) and view/from-tf.ts's
    // matching pull-side fallback, so a pull → rebuild round-trip resolves to
    // the same terraform address instead of planning a destroy+recreate.
    const layoutsForViewToTf = payload.layouts ??
        (mappedLayoutSections !== undefined && mappedLayoutSections.length > 0
            ? { layout: { sections: mappedLayoutSections } }
            : undefined);
    const { blocks: viewBlocks } = viewToTf(layoutsForViewToTf, payload.listViews, payload.calendarViews, payload.kanbanViews, payload.dashboardViews, undefined, payload.viewOrder, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        scope: "element",
        aspectName: payload.name ?? "",
        objectId,
        dashboardKeys: new Set(Object.keys(payload.dashboards ?? {})),
        orgRefs: ctx.orgRefs,
        diagnostics: ctx.diagnostics,
        fieldAddresses,
        widgetKeys: new Set(Object.keys(payload.widgets ?? {})),
    });
    blocks.push(...viewBlocks);
    const recordCreateFormForToTf = payload.recordCreateForm ??
        (mappedRecordCreateFormSections !== undefined && mappedRecordCreateFormSections.length > 0
            ? { sections: mappedRecordCreateFormSections }
            : undefined);
    const recordCreateForm = recordCreateFormToTf(recordCreateFormForToTf, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        scope: "element",
        objectId,
        diagnostics: ctx.diagnostics,
        fieldAddresses,
    });
    if (recordCreateForm !== undefined)
        blocks.push(recordCreateForm);
    blocks.push(...relationshipsToTf(payload.relationships, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        ownerType: "elementum_element",
        scope: "element",
        objectId,
        orgRefs: ctx.orgRefs,
        workspaceAspects: ctx.workspaceAspects,
        diagnostics: ctx.diagnostics,
    }));
    // Authored entries only. Creating an element also has the platform mint a
    // creator policy (userIds = [you]) that is NOT in this payload — pull
    // will see it; we never emit it here.
    for (const [index, entry] of (payload.accessPolicies ?? []).entries()) {
        const { block } = accessPolicyToTf(entry, index, {
            ownerTfLabel: ctx.appTfLabel,
            scope: "element",
            objectId,
            orgRefs: ctx.orgRefs,
            diagnostics: ctx.diagnostics,
            fieldAddresses,
            // An element has no service accounts of its own. Hand the sibling app's
            // authored bag to the shared resolver so a managed account becomes a
            // direct resource ref and Terraform sequences same-apply creation.
            resolveServiceAccountApp: (appRefName) => {
                const app = ctx.workspaceAspects?.get(workspaceAspectKey("app", appRefName));
                if (app === undefined)
                    return undefined;
                const serviceAccounts = app.streamRootEntity?.payload?.serviceAccounts;
                return {
                    appTfLabel: app.tfLabel,
                    appId: expr.resourceAttr(APP_RESOURCE_TYPE, app.tfLabel, ["id"]),
                    ...(serviceAccounts !== undefined ? { serviceAccounts } : {}),
                };
            },
        });
        blocks.push(block);
    }
    blocks.push(...rolesToTf(payload.roles, {
        ownerRefName: ctx.appRefName,
        ownerTfLabel: ctx.appTfLabel,
        scope: "element",
        objectId,
        orgRefs: ctx.orgRefs,
        diagnostics: ctx.diagnostics,
    }));
    blocks.unshift({
        kind: "resource",
        type: ELEMENT_RESOURCE_TYPE,
        label: ctx.appTfLabel,
        attrs: elementAttrs,
    });
    return { blocks, fieldAddresses, fieldNames };
}
